/**
 * This is a helper method to infer the type of bindings for this router off other rspc types.
 * The inferred type is what is generated by Rust.
 * @example
 * const rspc = createReactQueryHooks<Operations>();
 * type Bindings = inferBindingsType<typeof rspc>
 */
declare type inferBindingsType<TBindings extends Procedures | ProcedureLike> = TBindings extends ProcedureLike ? TBindings["_rspc_def"] : TBindings;

declare type inferProcedureKey<TBindings extends Procedures | ProcedureLike, TOperation extends keyof Procedures, T extends inferBindingsType<TBindings>[TOperation]["key"][0]> = Extract<inferBindingsType<TBindings>[TOperation], {
    key: procedureKey<T>;
}>["key"];

declare type inferProcedureResult<TBindings extends Procedures | ProcedureLike, TOperation extends keyof Procedures, T extends inferBindingsType<TBindings>[TOperation]["key"][0]> = Extract<inferBindingsType<TBindings>[TOperation], {
    key: procedureKey<T>;
}>["result"];

declare type procedureKey<T extends string> = [
    T
] | [
    T, /* input */
    any
];

/**
 * The key to an operation
 */
declare type ProcedureKey = [
    string
] | [
    string, /* input */
    any
];

/**
 * A type which allows inferring the type of the bindings
 */
declare type ProcedureLike = {
    _rspc_def: Procedures;
};

/**
 * This type represents the Typescript bindings which are generated from the router by Rust.
 */
declare type Procedures = {
    queries: {
        key: ProcedureKey;
        result: any;
    };
    mutations: {
        key: ProcedureKey;
        result: any;
    };
    subscriptions: {
        key: ProcedureKey;
        result: any;
    };
};

declare class RSPCError {
    code: number;
    message: string;
    constructor(code: number, message: string);
}

interface Transport {
    transformer?: ClientTransformer;
    clientSubscriptionCallback?: (id: string, key: string, value: any) => void;
    doRequest(operation: OperationType, key: ProcedureKey): Promise<any>;
}

declare class WebsocketTransport implements Transport {
    private url;
    private ws;
    private requestMap;
    transformer?: ClientTransformer;
    clientSubscriptionCallback?: (id: string, key: string, value: any) => void;
    constructor(url: string);
    attachEventListeners(): void;
    reconnect(timeoutIndex?: number): Promise<void>;
    doRequest(operation: OperationType, key: ProcedureKey): Promise<any>;
}
